// Expune global
window.ACATISTE = ACATISTE;

// Utilitar: returnează lista de acatiste pentru hub
function getListaAcatiste() {
  return Object.values(ACATISTE).map(a => ({
    slug: a.slug,
    titlu: a.titlu,
    titluScurt: a.titluScurt,
    icon: a.icon,
    descriere: a.descriere
  }));
}
window.getListaAcatiste = getListaAcatiste;
